-- faq (12 blocks)
INSERT INTO public.page_content (page_key, title, blocks, updated_at)
VALUES ('faq', 'FAQ', '[{"id":"faq-0","type":"heading","data":{"text":"Orders & Shipping","level":2}},{"id":"faq-1","type":"accordion","data":{"items":[{"q":"How long does shipping take?","a":"Standard shipping is 5–7 business days. Expedited shipping delivers in 2–3 business days, and priority shipping arrives within 1–2 business days. Expedited and priority options are available at checkout."},{"q":"Do you ship internationally?","a":"Not yet — but we''re working on it. International shipping is coming soon. Sign up for our newsletter to be the first to know when it launches."},{"q":"How do I track my order?","a":"You''ll receive a tracking email with carrier details as soon as your order ships. You can also check order status anytime from your account dashboard."},{"q":"Can I change or cancel my order?","a":"Orders are processed quickly. Contact us within 1 hour of placing your order at info@styleeternal.com and we''ll do our best to accommodate changes or cancellations."},{"q":"How long does processing take?","a":"Orders are processed within 1–3 business days before shipping. During high-volume drops, processing may take an additional day."},{"q":"Is there a free shipping threshold?","a":"Yes — free standard shipping on all orders over $150. No codes needed, it''s applied automatically at checkout."}]}},{"id":"faq-2","type":"heading","data":{"text":"Products","level":2}},{"id":"faq-3","type":"accordion","data":{"items":[{"q":"What sizes do you carry and how do they fit?","a":"Tops run S through XXL. Bottoms run 28–38. Most pieces are cut in an oversized or relaxed fit — that''s the Style Eternal signature. Check the fit note on each product page. When in doubt, size down for a less relaxed silhouette."},{"q":"Are your garments pre-shrunk?","a":"All garment-washed pieces are pre-shrunk. Follow the care instructions on the label to maintain the intended fit and feel over time."},{"q":"What does ''Limited'' mean?","a":"Limited pieces are produced in intentionally small quantities. Once they sell out, they''re gone — no restocks. They move to the Archive as a permanent record of the drop."},{"q":"What fabric weights do you use?","a":"Our tees are 280gsm+ heavyweight cotton. Hoodies and outerwear are 400gsm+ French terry or fleece. We don''t do thin basics — everything has real substance."},{"q":"How should I care for printed pieces?","a":"Turn the garment inside out and wash cold on a gentle cycle. Hang dry or tumble dry on low heat. Avoid ironing directly on prints to preserve the design."}]}},{"id":"faq-4","type":"heading","data":{"text":"Returns & Exchanges","level":2}},{"id":"faq-5","type":"accordion","data":{"items":[{"q":"What is your return policy?","a":"We accept returns on unworn items with tags attached within 30 days of delivery. Items must be in original condition — no wear, wash, or alterations."},{"q":"How do I initiate a return?","a":"Email info@styleeternal.com with your order number and reason for the return. We''ll send you a prepaid return label within 24 hours."},{"q":"How do exchanges work?","a":"Contact us and we''ll help you swap sizes or colorways, subject to availability. Your first exchange on any order is free."},{"q":"What if my item arrives damaged?","a":"Contact us at info@styleeternal.com with photos of the damage. We''ll arrange a full replacement or refund — no need to return the damaged item."},{"q":"How long until I receive my refund?","a":"Refunds are processed within 5–7 business days after we receive and inspect the returned item. Your original payment method will be credited."}]}},{"id":"faq-6","type":"heading","data":{"text":"Drops & Collections","level":2}},{"id":"faq-7","type":"accordion","data":{"items":[{"q":"When is the next drop?","a":"Drop dates are announced through our newsletter and social channels first. Subscribe to get notified before anything goes live."},{"q":"How do I get notified about new releases?","a":"Sign up for the Style Eternal newsletter at shopstyleeternal.com. Subscribers always get early access and first notice on upcoming drops."},{"q":"Will sold-out items ever restock?","a":"Limited drops don''t restock — that''s what makes them limited. Once they sell out, they move to the Archive as a permanent record. Core collection items may be replenished."},{"q":"What is the Archive?","a":"The Archive is a record of every past release. It preserves the history of each collection and drop, even after items have sold out."}]}},{"id":"faq-8","type":"heading","data":{"text":"Account & Rewards","level":2}},{"id":"faq-9","type":"accordion","data":{"items":[{"q":"How do I join the rewards program?","a":"Create an account on shopstyleeternal.com and you''re automatically enrolled. No extra steps — start earning from your first purchase."},{"q":"How do reward tiers work?","a":"There are four tiers based on total spend: Foundation, Established, Permanent, and Eternal. Each tier unlocks better perks, from early access to exclusive drops."},{"q":"Do my points expire?","a":"No — your points never expire. They stay in your account as long as it''s active."},{"q":"How do I earn points?","a":"You earn 1 point for every dollar spent. Points accrue automatically with each completed order."}]}},{"id":"faq-10","type":"heading","data":{"text":"Brand","level":2}},{"id":"faq-11","type":"accordion","data":{"items":[{"q":"Where is Style Eternal based?","a":"New Jersey. Every piece is designed here. It''s where we come from and it shows in everything we make."},{"q":"Do you do collaborations?","a":"We''re open to the right partnerships — artists, makers, and community voices that align with our values. Reach out via the contact page."},{"q":"What does EST. 2021 mean?","a":"2021 is the year Style Eternal was founded. It marks the beginning of the brand and everything we''ve built since."}]}}]'::jsonb, NOW())
ON CONFLICT (page_key) DO NOTHING;

-- tos (49 blocks)
INSERT INTO public.page_content (page_key, title, blocks, updated_at)
VALUES ('tos', 'Terms of Service', '[{"id":"tos-0","type":"heading","data":{"text":"1. ACCEPTANCE OF TERMS","level":2}},{"id":"tos-1","type":"paragraph","data":{"text":"Welcome to shopstyleeternal.com (the “Site”), operated by Style Eternal LLC (“Style Eternal,” “we,” “us,” or “our”). By accessing or using the Site, creating an account, or placing an order, you agree to be bound by these Terms & Conditions (“Terms”). If you do not agree with any part of these Terms, you must not use the Site."}},{"id":"tos-2","type":"heading","data":{"text":"2. ELIGIBILITY","level":2}},{"id":"tos-3","type":"paragraph","data":{"text":"You must be at least eighteen (18) years of age to use this Site or make a purchase. If you are between thirteen (13) and seventeen (17) years old, you may use the Site only with the involvement and consent of a parent or legal guardian who agrees to be bound by these Terms. By using the Site, you represent and warrant that you meet these eligibility requirements."}},{"id":"tos-4","type":"heading","data":{"text":"3. ACCOUNT RESPONSIBILITIES","level":2}},{"id":"tos-5","type":"paragraph","data":{"text":"When you create an account on the Site, you are responsible for maintaining the confidentiality of your login credentials and for all activity that occurs under your account. You agree to:"}},{"id":"tos-6","type":"list","data":{"style":"bullet","items":["Provide accurate, current, and complete information during registration.","Update your account information promptly if it changes.","Notify us immediately at info@styleeternal.com if you suspect unauthorized access to your account.","Not share your account credentials with any third party."]}},{"id":"tos-7","type":"paragraph","data":{"text":"Style Eternal reserves the right to suspend or terminate accounts that violate these Terms or that we reasonably believe have been compromised."}},{"id":"tos-8","type":"heading","data":{"text":"4. PRODUCT DESCRIPTIONS & PRICING","level":2}},{"id":"tos-9","type":"paragraph","data":{"text":"We make every effort to display our products and their colors, materials, and dimensions as accurately as possible. However, the actual appearance of items may vary slightly from images on the Site due to differences in monitors and display settings."}},{"id":"tos-10","type":"paragraph","data":{"text":"All prices are listed in United States Dollars (USD) and are subject to change without notice. Prices do not include applicable taxes or shipping fees, which are calculated at checkout. In the event of a pricing error, Style Eternal reserves the right to cancel any orders placed at the incorrect price and will notify you promptly. A price listed on the Site does not constitute a binding offer until the order has been confirmed."}},{"id":"tos-11","type":"heading","data":{"text":"5. ORDER ACCEPTANCE & CANCELLATION","level":2}},{"id":"tos-12","type":"paragraph","data":{"text":"Placing an order on the Site constitutes an offer to purchase. All orders are subject to acceptance by Style Eternal. We may, at our sole discretion, refuse or cancel any order for any reason, including but not limited to:"}},{"id":"tos-13","type":"list","data":{"style":"bullet","items":["Product unavailability or inventory errors.","Pricing or descriptive errors on the Site.","Suspected fraudulent or unauthorized activity.","Orders that exceed reasonable personal-use quantities."]}},{"id":"tos-14","type":"paragraph","data":{"text":"If your order is cancelled after payment has been processed, a full refund will be issued to your original payment method. You may request cancellation of an order before it has shipped by contacting us at info@styleeternal.com. Once an order has shipped, it cannot be cancelled and must be handled through our returns process."}},{"id":"tos-15","type":"heading","data":{"text":"6. PAYMENT TERMS","level":2}},{"id":"tos-16","type":"paragraph","data":{"text":"All payments are processed securely through Stripe, a PCI-DSS Level 1 certified payment processor. Style Eternal does not store, process, or have access to your full credit card number, expiration date, or CVV. We accept major credit cards, debit cards, and other payment methods as displayed at checkout."}},{"id":"tos-17","type":"paragraph","data":{"text":"By submitting an order, you represent that you are authorized to use the selected payment method and that the billing information you provide is accurate. You agree to pay the total amount of your order, including product price, applicable taxes, and shipping fees. If your payment method is declined or cannot be verified, we reserve the right to cancel your order."}},{"id":"tos-18","type":"heading","data":{"text":"7. SHIPPING","level":2}},{"id":"tos-19","type":"paragraph","data":{"text":"Style Eternal currently ships to addresses within the United States only. Orders are processed within one (1) to three (3) business days after payment confirmation. Estimated delivery times are provided at checkout and begin after the order has been processed and shipped."}},{"id":"tos-20","type":"paragraph","data":{"text":"Shipping times are estimates and are not guaranteed. Style Eternal is not responsible for delays caused by shipping carriers, weather events, customs processing, or other circumstances beyond our control. Risk of loss and title to products pass to you upon delivery to the carrier."}},{"id":"tos-21","type":"paragraph","data":{"text":"If your order arrives damaged or with missing items, please contact us within seven (7) days of delivery at info@styleeternal.com with photos of the damage and your order number."}},{"id":"tos-22","type":"heading","data":{"text":"8. RETURNS & EXCHANGES","level":2}},{"id":"tos-23","type":"paragraph","data":{"text":"We offer a thirty (30) day return policy from the date of delivery. To be eligible for a return, items must be unworn, unwashed, free of odors and pet hair, and in their original condition with all tags attached. Items must be returned in the original packaging where provided."}},{"id":"tos-24","type":"paragraph","data":{"text":"The following items are **not eligible** for return or exchange:"}},{"id":"tos-25","type":"list","data":{"style":"bullet","items":["Limited-edition or collaboration pieces.","Items marked as “Final Sale.”","Gift cards.","Items that have been worn, altered, or damaged by the customer."]}},{"id":"tos-26","type":"paragraph","data":{"text":"For full details and to initiate a return, please visit our [Returns & Exchanges](/returns) page. Return shipping costs are the responsibility of the customer unless the return is due to a Style Eternal error (e.g., incorrect or defective item)."}},{"id":"tos-27","type":"heading","data":{"text":"9. INTELLECTUAL PROPERTY","level":2}},{"id":"tos-28","type":"paragraph","data":{"text":"All content on the Site — including but not limited to designs, graphics, illustrations, photographs, text, logos, brand marks, product names, slogans, and the overall look and feel of the Site — is the exclusive property of Style Eternal LLC or its licensors and is protected by United States and international copyright, trademark, and other intellectual property laws."}},{"id":"tos-29","type":"paragraph","data":{"text":"You may not reproduce, distribute, modify, create derivative works from, publicly display, or otherwise use any of our intellectual property without prior written permission from Style Eternal. Unauthorized use may result in legal action."}},{"id":"tos-30","type":"heading","data":{"text":"10. USER-GENERATED CONTENT","level":2}},{"id":"tos-31","type":"paragraph","data":{"text":"By submitting any content to the Site — including reviews, photos, comments, or social media posts tagged with our brand — you grant Style Eternal a non-exclusive, worldwide, royalty-free, perpetual, irrevocable license to use, reproduce, modify, publish, translate, distribute, and display such content in any media for marketing and promotional purposes."}},{"id":"tos-32","type":"paragraph","data":{"text":"You represent that you own or have the necessary rights to the content you submit and that it does not infringe on the intellectual property rights, privacy rights, or any other rights of any third party. Style Eternal reserves the right to remove any user-generated content at our sole discretion."}},{"id":"tos-33","type":"heading","data":{"text":"11. LIMITATION OF LIABILITY","level":2}},{"id":"tos-34","type":"paragraph","data":{"text":"To the fullest extent permitted by applicable law, Style Eternal, its officers, directors, employees, agents, and affiliates shall not be liable for any indirect, incidental, special, consequential, or punitive damages — including but not limited to loss of profits, data, or goodwill — arising out of or in connection with your use of the Site, your inability to use the Site, or any products purchased through the Site, regardless of the theory of liability."}},{"id":"tos-35","type":"paragraph","data":{"text":"In no event shall Style Eternal''s total liability exceed the amount you paid for the specific product or order giving rise to the claim. Some jurisdictions do not allow the exclusion or limitation of certain damages; in such jurisdictions, our liability shall be limited to the greatest extent permitted by law."}},{"id":"tos-36","type":"heading","data":{"text":"12. INDEMNIFICATION","level":2}},{"id":"tos-37","type":"paragraph","data":{"text":"You agree to indemnify, defend, and hold harmless Style Eternal, its officers, directors, employees, agents, and affiliates from and against any and all claims, liabilities, damages, losses, costs, and expenses (including reasonable attorneys'' fees) arising out of or related to your use of the Site, your violation of these Terms, your violation of any applicable law, or your infringement of any third-party rights."}},{"id":"tos-38","type":"heading","data":{"text":"13. GOVERNING LAW","level":2}},{"id":"tos-39","type":"paragraph","data":{"text":"These Terms and any disputes arising out of or related to them or the Site shall be governed by and construed in accordance with the laws of the State of New Jersey, United States, without regard to its conflict-of-law principles. You consent to the exclusive jurisdiction and venue of the state and federal courts located in the State of New Jersey for the resolution of any such disputes."}},{"id":"tos-40","type":"heading","data":{"text":"14. DISPUTE RESOLUTION","level":2}},{"id":"tos-41","type":"paragraph","data":{"text":"Before initiating any formal legal proceedings, you agree to first contact us at info@styleeternal.com and attempt to resolve the dispute informally for at least thirty (30) days. If the dispute cannot be resolved informally, either party may pursue resolution through binding arbitration administered under the rules of the American Arbitration Association, conducted in the State of New Jersey."}},{"id":"tos-42","type":"paragraph","data":{"text":"You agree that any arbitration or legal proceeding shall be conducted on an individual basis and not as a class action, class arbitration, or any other representative proceeding. You waive any right to participate in a class action lawsuit or class-wide arbitration against Style Eternal."}},{"id":"tos-43","type":"heading","data":{"text":"15. SEVERABILITY","level":2}},{"id":"tos-44","type":"paragraph","data":{"text":"If any provision of these Terms is found by a court of competent jurisdiction to be invalid, illegal, or unenforceable, the remaining provisions shall continue in full force and effect. The invalid or unenforceable provision shall be modified to the minimum extent necessary to make it valid and enforceable while preserving the original intent of the provision."}},{"id":"tos-45","type":"heading","data":{"text":"16. MODIFICATIONS TO TERMS","level":2}},{"id":"tos-46","type":"paragraph","data":{"text":"Style Eternal reserves the right to update or modify these Terms at any time without prior notice. Changes become effective immediately upon posting to the Site. The “Last updated” date at the top of this page reflects when the Terms were most recently revised. Your continued use of the Site after any changes constitutes your acceptance of the revised Terms. We encourage you to review these Terms periodically."}},{"id":"tos-47","type":"heading","data":{"text":"17. CONTACT","level":2}},{"id":"tos-48","type":"paragraph","data":{"text":"If you have any questions, concerns, or requests regarding these Terms & Conditions, please contact us at info@styleeternal.com."}}]'::jsonb, NOW())
ON CONFLICT (page_key) DO NOTHING;

-- privacy (41 blocks)
INSERT INTO public.page_content (page_key, title, blocks, updated_at)
VALUES ('privacy', 'Privacy Policy', '[{"id":"privacy-0","type":"heading","data":{"text":"1. OVERVIEW","level":2}},{"id":"privacy-1","type":"paragraph","data":{"text":"Style Eternal LLC (“Style Eternal,” “we,” “us,” or “our”) respects your privacy and is committed to protecting the personal information you share with us. This Privacy Policy explains how we collect, use, disclose, and safeguard your information when you visit shopstyleeternal.com (the “Site”), create an account, make a purchase, or interact with us. By using the Site, you consent to the practices described in this policy."}},{"id":"privacy-2","type":"heading","data":{"text":"2. INFORMATION WE COLLECT","level":2}},{"id":"privacy-3","type":"paragraph","data":{"text":"**Information You Provide**"}},{"id":"privacy-4","type":"list","data":{"style":"bullet","items":["**Account & order information:** name, email address, shipping address, and phone number when you create an account or place an order.","**Payment information:** credit/debit card details are collected and processed directly by Stripe. Style Eternal does not store, access, or retain your full card number, expiration date, or CVV.","**Newsletter subscription:** email address when you opt in to marketing communications.","**Customer communications:** any information you provide when contacting customer support or submitting reviews."]}},{"id":"privacy-5","type":"paragraph","data":{"text":"**Information Collected Automatically**"}},{"id":"privacy-6","type":"list","data":{"style":"bullet","items":["**Usage data:** pages visited, time spent on pages, referral URLs, browser type, operating system, and device information.","**Cookies & similar technologies:** we use cookies to operate the Site, analyze traffic, and deliver relevant content. See Section 5 for details.","**IP address:** collected automatically by our hosting provider for security and analytics purposes."]}},{"id":"privacy-7","type":"heading","data":{"text":"3. HOW WE USE YOUR INFORMATION","level":2}},{"id":"privacy-8","type":"paragraph","data":{"text":"We use the information we collect for the following purposes:"}},{"id":"privacy-9","type":"list","data":{"style":"bullet","items":["**Order fulfillment:** processing, shipping, and delivering your orders; sending order confirmations, shipping updates, and delivery notifications.","**Account management:** creating and maintaining your account, authenticating logins, and managing your profile.","**Marketing communications:** sending promotional emails, product announcements, and exclusive offers — only with your explicit consent. You may unsubscribe at any time.","**Site improvement:** analyzing usage patterns to improve the shopping experience, site performance, and product offerings.","**Fraud prevention & security:** detecting and preventing fraudulent transactions, unauthorized access, and other illegal activities.","**Legal compliance:** fulfilling legal obligations and responding to lawful requests from public authorities."]}},{"id":"privacy-10","type":"heading","data":{"text":"4. INFORMATION SHARING","level":2}},{"id":"privacy-11","type":"paragraph","data":{"text":"Style Eternal does **not** sell, rent, or trade your personal information to third parties. We share your data only with the following trusted service providers who assist us in operating the Site and fulfilling orders:"}},{"id":"privacy-12","type":"list","data":{"style":"bullet","items":["**Stripe** — payment processing. Stripe processes your payment information in accordance with their own privacy policy.","**Resend** — transactional and marketing email delivery.","**Vercel** — website hosting and serverless function execution.","**Supabase** — database and authentication infrastructure."]}},{"id":"privacy-13","type":"paragraph","data":{"text":"Each service provider is contractually obligated to protect your information and use it only for the specific services they provide to us. We may also disclose information when required by law, to respond to legal process, or to protect the rights, property, or safety of Style Eternal and its customers."}},{"id":"privacy-14","type":"heading","data":{"text":"5. COOKIES & TRACKING TECHNOLOGIES","level":2}},{"id":"privacy-15","type":"paragraph","data":{"text":"We use cookies and similar technologies to enhance your experience on the Site. The cookies we use fall into the following categories:"}},{"id":"privacy-16","type":"list","data":{"style":"bullet","items":["**Necessary cookies** (always active) — essential for Site functionality, including authentication, cart persistence, and security features. These cannot be disabled.","**Analytics cookies** (with consent) — Google Analytics 4 (GA4) is used to understand how visitors interact with the Site. These cookies are only activated with your consent.","**Marketing cookies** (with consent) — Meta Pixel may be used to measure the effectiveness of advertising campaigns. These cookies are only activated with your consent."]}},{"id":"privacy-17","type":"paragraph","data":{"text":"We honor Global Privacy Control (GPC) and Do Not Track (DNT) signals sent by your browser. When a GPC or DNT signal is detected, analytics and marketing cookies are not loaded."}},{"id":"privacy-18","type":"paragraph","data":{"text":"You can manage your cookie preferences at any time through our [Privacy Choices](/privacy-choices) page or through your browser settings."}},{"id":"privacy-19","type":"heading","data":{"text":"6. DATA SECURITY","level":2}},{"id":"privacy-20","type":"paragraph","data":{"text":"We implement industry-standard security measures to protect your personal information, including:"}},{"id":"privacy-21","type":"list","data":{"style":"bullet","items":["SSL/TLS encryption for all data transmitted between your browser and the Site.","Secure payment processing through Stripe — no sensitive payment data is stored on our servers.","Database-level encryption and access controls through Supabase.","No storage of passwords in plaintext; all credentials are securely hashed."]}},{"id":"privacy-22","type":"paragraph","data":{"text":"While we strive to protect your information, no method of transmission over the Internet or electronic storage is 100% secure. We cannot guarantee absolute security but are committed to promptly addressing any breach in accordance with applicable law."}},{"id":"privacy-23","type":"heading","data":{"text":"7. DATA RETENTION","level":2}},{"id":"privacy-24","type":"paragraph","data":{"text":"We retain your personal information only for as long as necessary to fulfill the purposes for which it was collected, including:"}},{"id":"privacy-25","type":"list","data":{"style":"bullet","items":["**Account data:** retained for the lifetime of your account. You may request deletion at any time.","**Order records:** retained for a minimum of five (5) years for tax, legal, and dispute-resolution purposes.","**Marketing preferences:** retained until you unsubscribe or request deletion.","**Usage & analytics data:** aggregated and anonymized data may be retained indefinitely for statistical analysis."]}},{"id":"privacy-26","type":"paragraph","data":{"text":"When personal data is no longer needed, it is securely deleted or anonymized."}},{"id":"privacy-27","type":"heading","data":{"text":"8. YOUR RIGHTS","level":2}},{"id":"privacy-28","type":"paragraph","data":{"text":"Depending on your location, you may have the following rights regarding your personal information:"}},{"id":"privacy-29","type":"list","data":{"style":"bullet","items":["**Right to access:** request a copy of the personal data we hold about you.","**Right to correction:** request that we update or correct inaccurate information.","**Right to deletion:** request that we delete your personal data, subject to legal retention requirements.","**Right to opt out:** opt out of marketing communications at any time by clicking the “unsubscribe” link in any marketing email or contacting us directly."]}},{"id":"privacy-30","type":"paragraph","data":{"text":"To exercise any of these rights, please contact us at info@styleeternal.com. We will respond to your request within thirty (30) days."}},{"id":"privacy-31","type":"heading","data":{"text":"9. CHILDREN''S PRIVACY","level":2}},{"id":"privacy-32","type":"paragraph","data":{"text":"The Site is not intended for children under the age of thirteen (13). We do not knowingly collect personal information from children under 13. If we become aware that we have inadvertently collected information from a child under 13, we will take steps to delete that information as promptly as possible. If you believe a child under 13 has provided us with personal information, please contact us at info@styleeternal.com."}},{"id":"privacy-33","type":"heading","data":{"text":"10. CALIFORNIA PRIVACY RIGHTS (CCPA)","level":2}},{"id":"privacy-34","type":"paragraph","data":{"text":"If you are a California resident, the California Consumer Privacy Act (CCPA) grants you additional rights regarding your personal information:"}},{"id":"privacy-35","type":"list","data":{"style":"bullet","items":["**Right to know:** you may request that we disclose the categories and specific pieces of personal information we have collected about you, the categories of sources, the business purpose for collection, and the categories of third parties with whom we share it.","**Right to delete:** you may request deletion of your personal information, subject to certain exceptions under the CCPA.","**Right to non-discrimination:** we will not discriminate against you for exercising any of your CCPA rights.","**No sale of personal information:** Style Eternal does not sell personal information as defined by the CCPA."]}},{"id":"privacy-36","type":"paragraph","data":{"text":"To submit a CCPA request, email us at info@styleeternal.com with the subject line “CCPA Request.” We may ask you to verify your identity before processing your request."}},{"id":"privacy-37","type":"heading","data":{"text":"11. CHANGES TO THIS POLICY","level":2}},{"id":"privacy-38","type":"paragraph","data":{"text":"Style Eternal reserves the right to update this Privacy Policy at any time. When we make changes, we will revise the “Last updated” date at the top of this page. For material changes, we may also notify you via email or a prominent notice on the Site. Your continued use of the Site after any changes constitutes your acceptance of the revised policy. We encourage you to review this Privacy Policy periodically."}},{"id":"privacy-39","type":"heading","data":{"text":"12. CONTACT","level":2}},{"id":"privacy-40","type":"paragraph","data":{"text":"If you have any questions, concerns, or requests regarding this Privacy Policy or the way we handle your personal information, please contact us at info@styleeternal.com."}}]'::jsonb, NOW())
ON CONFLICT (page_key) DO NOTHING;

-- about (17 blocks)
INSERT INTO public.page_content (page_key, title, blocks, updated_at)
VALUES ('about', 'About', '[{"id":"about-0","type":"heading","data":{"text":"THE STORY","level":2}},{"id":"about-1","type":"paragraph","data":{"text":"Style Eternal didn''t start with a business plan. It started with a feeling — that what you wear carries weight, and the right piece can make you feel permanent in a world that forgets fast."}},{"id":"about-2","type":"heading","data":{"text":"WHERE WE STARTED","level":2}},{"id":"about-3","type":"paragraph","data":{"text":"We came up in New Jersey — concrete, cold mornings, corner-store runs. Style wasn''t optional where we''re from. It was how you told the world you still gave a damn. That energy is the foundation of everything we build."}},{"id":"about-4","type":"heading","data":{"text":"THE CRAFT","level":2}},{"id":"about-5","type":"paragraph","data":{"text":"280gsm tees. 400gsm hoodies. Every piece starts with fabric that has real weight — because cheap material falls apart and we don''t make disposable clothing."}},{"id":"about-6","type":"paragraph","data":{"text":"We garment-wash for character, screen-print for durability, and cut oversized because that''s how streetwear actually lives on a body. No shortcuts on construction. No compromises on feel."}},{"id":"about-7","type":"heading","data":{"text":"FOUNDER''S NOTE","level":2}},{"id":"about-8","type":"paragraph","data":{"text":"“I didn''t start this brand to follow the industry. I started it because the streets I grew up on deserve a label that takes them seriously. Every piece we make carries that weight.” — Chino, Founder"}},{"id":"about-9","type":"heading","data":{"text":"THE STANDARD","level":2}},{"id":"about-10","type":"paragraph","data":{"text":"**Heavyweight Materials** — 280–400gsm fabrics. French terry. Combed cotton. Canvas. Nothing lightweight. Nothing disposable."}},{"id":"about-11","type":"paragraph","data":{"text":"**Built-In Character** — Garment-washed finishes. Distressed treatments. Every piece feels broken in, not brand new."}},{"id":"about-12","type":"paragraph","data":{"text":"**Real Graphics** — Screen-printed and embroidered. Every design references a place, a memory, or a principle."}},{"id":"about-13","type":"paragraph","data":{"text":"**Intentional Fit** — Oversized and relaxed cuts that honor how streetwear actually moves on a body."}},{"id":"about-14","type":"heading","data":{"text":"THE VISION","level":2}},{"id":"about-15","type":"paragraph","data":{"text":"Style Eternal is built on permanence over trend. We design pieces that carry emotional weight — graphics rooted in love, death, and rebirth. The symbols mean something. The work outlasts the season."}},{"id":"about-16","type":"paragraph","data":{"text":"This isn''t fast fashion with a streetwear skin. Every collection is a statement about what deserves to endure. We make clothes for people who feel something when they get dressed."}}]'::jsonb, NOW())
ON CONFLICT (page_key) DO NOTHING;

-- returns (24 blocks)
INSERT INTO public.page_content (page_key, title, blocks, updated_at)
VALUES ('returns', 'Returns', '[{"id":"returns-0","type":"paragraph","data":{"text":"We stand behind everything we make. If something isn''t right, we''ll make it right — no hassle, no runaround."}},{"id":"returns-1","type":"heading","data":{"text":"AT A GLANCE","level":2}},{"id":"returns-2","type":"list","data":{"style":"bullet","items":["**30-Day Window** — from delivery date.","**Free First Exchange** — size or color swap.","**Full Refund** — to original payment method.","**5–7 Days** — refund processing time."]}},{"id":"returns-3","type":"heading","data":{"text":"RETURN ELIGIBILITY","level":2}},{"id":"returns-4","type":"paragraph","data":{"text":"We accept returns within **30 days of delivery**. To qualify, items must meet all of the following conditions:"}},{"id":"returns-5","type":"list","data":{"style":"bullet","items":["Unworn and unwashed.","Unaltered — no tailoring, hemming, or modifications.","All original tags still attached.","Original packaging preferred (branded bag, tissue wrap, etc.)."]}},{"id":"returns-6","type":"heading","data":{"text":"HOW TO START A RETURN","level":2}},{"id":"returns-7","type":"paragraph","data":{"text":"Email us at info@styleeternal.com with your **order number** and **reason for return**. Our team will respond within 24 hours with a prepaid return shipping label."}},{"id":"returns-8","type":"paragraph","data":{"text":"Pack the item securely — original packaging is preferred but not required — and drop it off at any carrier location. Once we receive and inspect the item, your refund will be processed within **5–7 business days** to your original payment method."}},{"id":"returns-9","type":"heading","data":{"text":"RETURN PROCESS","level":2}},{"id":"returns-10","type":"list","data":{"style":"bullet","items":["**Email Us** — send your order number and reason to info@styleeternal.com.","**Receive Label** — we''ll send a prepaid return label within 24 hours.","**Ship Back** — pack the item and drop it off at any carrier location.","**Refund Processed** — refund issued within 5–7 business days after inspection."]}},{"id":"returns-11","type":"heading","data":{"text":"REFUND DETAILS","level":2}},{"id":"returns-12","type":"paragraph","data":{"text":"Refunds are issued to your **original payment method** within **5–7 business days** after we receive and inspect the returned item. Please allow an additional 3–5 business days for the refund to appear on your statement, depending on your bank or card issuer."}},{"id":"returns-13","type":"heading","data":{"text":"EXCHANGES","level":2}},{"id":"returns-14","type":"paragraph","data":{"text":"Need a different size or colorway? Email us at info@styleeternal.com with your order number and the size or color you''d like instead. We''ll check availability and arrange the swap."}},{"id":"returns-15","type":"paragraph","data":{"text":"Your **first exchange is free** — no extra shipping charges. Subsequent exchanges are subject to standard return shipping costs."}},{"id":"returns-16","type":"paragraph","data":{"text":"Exchanges are subject to availability. If your desired item is out of stock, we''ll issue a full refund instead."}},{"id":"returns-17","type":"heading","data":{"text":"RETURN SHIPPING","level":2}},{"id":"returns-18","type":"list","data":{"style":"bullet","items":["**Domestic (US)** — prepaid label provided.","**International** — customer pays return shipping."]}},{"id":"returns-19","type":"heading","data":{"text":"DAMAGED OR INCORRECT ORDERS","level":2}},{"id":"returns-20","type":"paragraph","data":{"text":"Received a damaged or incorrect item? [Contact us](/client-services) immediately with your order number and **photos of the issue**. We''ll arrange a full replacement or refund — no return needed in most cases."}},{"id":"returns-21","type":"paragraph","data":{"text":"Please report any issues within 48 hours of delivery for fastest resolution."}},{"id":"returns-22","type":"heading","data":{"text":"EXCEPTIONS","level":2}},{"id":"returns-23","type":"list","data":{"style":"bullet","items":["**Final Sale items** — not eligible for returns or exchanges. All sales are final.","**Limited Edition / Sold Out pieces** — non-returnable once purchased due to limited availability.","**Pre-order items** — may have different return windows; check the product page for specific terms.","**Custom or made-to-order items** — non-returnable. Custom pieces are final sale."]}}]'::jsonb, NOW())
ON CONFLICT (page_key) DO NOTHING;

-- shipping (20 blocks)
INSERT INTO public.page_content (page_key, title, blocks, updated_at)
VALUES ('shipping', 'Shipping', '[{"id":"shipping-0","type":"paragraph","data":{"text":"Every order is handled with care — custom packed, sealed, and shipped to your door. Currently shipping within the United States only."}},{"id":"shipping-1","type":"heading","data":{"text":"SHIPPING OPTIONS","level":2}},{"id":"shipping-2","type":"list","data":{"style":"bullet","items":["**Standard Shipping** — 5–7 business days. Free on orders over $150 ($8.95 for orders under $150).","**Expedited Shipping** — 2–3 business days. $14.95, available at checkout.","**Priority Shipping** — 1–2 business days. $24.95, signature required on delivery."]}},{"id":"shipping-3","type":"heading","data":{"text":"ORDER PROCESSING","level":2}},{"id":"shipping-4","type":"paragraph","data":{"text":"Orders are processed within **1–3 business days**. You will receive a confirmation email with tracking information once your order ships."}},{"id":"shipping-5","type":"paragraph","data":{"text":"Orders placed after **2:00 PM EST** or on weekends and holidays will begin processing the next business day."}},{"id":"shipping-6","type":"heading","data":{"text":"TRACKING YOUR ORDER","level":2}},{"id":"shipping-7","type":"paragraph","data":{"text":"Once your order ships, you will receive an email with a **tracking number** and a link to follow your package in real time."}},{"id":"shipping-8","type":"paragraph","data":{"text":"You can also check order status anytime from your [account page](/account)."}},{"id":"shipping-9","type":"heading","data":{"text":"PACKAGING","level":2}},{"id":"shipping-10","type":"paragraph","data":{"text":"Every order is packed in custom branded packaging — tissue-wrapped, sealed, and shipped in reinforced mailers or boxes to ensure your pieces arrive in pristine condition."}},{"id":"shipping-11","type":"heading","data":{"text":"PRE-ORDERS","level":2}},{"id":"shipping-12","type":"paragraph","data":{"text":"Pre-order items ship within the lead time stated on the product page. You will receive a shipping confirmation with tracking once your pre-order item is dispatched."}},{"id":"shipping-13","type":"paragraph","data":{"text":"If your order contains both in-stock and pre-order items, they may ship separately at no additional cost."}},{"id":"shipping-14","type":"heading","data":{"text":"P.O. BOXES","level":2}},{"id":"shipping-15","type":"paragraph","data":{"text":"We do ship to P.O. boxes — however, only **standard shipping** is available for P.O. box addresses. Expedited and priority shipping require a physical street address."}},{"id":"shipping-16","type":"heading","data":{"text":"INTERNATIONAL SHIPPING","level":2}},{"id":"shipping-17","type":"paragraph","data":{"text":"Style Eternal currently ships within the **United States only**. International shipping is coming soon. Sign up for our newsletter to be the first to know when we expand."}},{"id":"shipping-18","type":"heading","data":{"text":"LOST OR DAMAGED PACKAGES","level":2}},{"id":"shipping-19","type":"paragraph","data":{"text":"If your package is lost, stolen, or arrives damaged, [contact us](/client-services) immediately with your order number. We''ll open an investigation and work to resolve the issue as quickly as possible — whether that means reshipping your order or issuing a full refund."}}]'::jsonb, NOW())
ON CONFLICT (page_key) DO NOTHING;
